import { useState, useEffect } from 'react'

const links = [
  { label: 'الرئيسية', href: '#hero' },
  { label: 'خدماتنا', href: '#services' },
  { label: 'من نحن', href: '#about' },
  { label: 'كيف نعمل', href: '#how' },
  { label: 'الأسعار', href: '#pricing' },
  { label: 'آراء العملاء', href: '#testimonials' },
]

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 50)
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <nav
      style={{
        position: 'fixed',
        top: 0,
        right: 0,
        left: 0,
        zIndex: 100,
        padding: scrolled ? '12px 24px' : '20px 24px',
        background: scrolled ? 'rgba(4,8,18,0.92)' : 'transparent',
        backdropFilter: scrolled ? 'blur(20px)' : 'none',
        borderBottom: scrolled ? '1px solid rgba(14,165,233,0.15)' : 'none',
        transition: 'all 0.4s ease',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}
    >
      {/* Logo */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <div style={{
          width: 40, height: 40,
          background: 'linear-gradient(135deg, #0ea5e9, #8b5cf6)',
          borderRadius: '10px',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: '18px', fontWeight: 900, color: 'white',
        }}>ذ</div>
        <span style={{ fontSize: '18px', fontWeight: 800, color: '#f1f5f9' }}>
          ذكاء <span className="gradient-text">الأعمال</span>
        </span>
      </div>

      {/* Desktop Links */}
      <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}
        className="hidden-mobile">
        {links.map((l) => (
          <a key={l.href} href={l.href} style={{
            color: '#94a3b8', textDecoration: 'none', padding: '6px 14px',
            borderRadius: '8px', fontSize: '14px', fontWeight: 500,
            transition: 'all 0.2s ease',
          }}
          onMouseEnter={(e) => {
            (e.target as HTMLElement).style.color = '#0ea5e9'
            ;(e.target as HTMLElement).style.background = 'rgba(14,165,233,0.08)'
          }}
          onMouseLeave={(e) => {
            (e.target as HTMLElement).style.color = '#94a3b8'
            ;(e.target as HTMLElement).style.background = 'transparent'
          }}>
            {l.label}
          </a>
        ))}
      </div>

      {/* CTA */}
      <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
        <a href="#contact" style={{
          padding: '8px 20px', borderRadius: '10px', fontSize: '14px',
          fontWeight: 600, cursor: 'pointer', textDecoration: 'none',
          color: '#0ea5e9', border: '1px solid rgba(14,165,233,0.4)',
          transition: 'all 0.3s',
          display: 'none',
        }} className="btn-outline">
          تواصل معنا
        </a>
        <a href="#pricing" className="neon-btn" style={{
          padding: '8px 22px', borderRadius: '10px', fontSize: '14px',
          fontWeight: 600, cursor: 'pointer', textDecoration: 'none',
          color: 'white',
        }}>
          ابدأ الآن
        </a>
      </div>
    </nav>
  )
}

