        borderRadius: '50%',
        pointerEvents: 'none',
      }} className="animate-rotate-slow" />
      <div style={{
        position: 'absolute', top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        width: 500, height: 500,
        border: '1px solid rgba(139,92,246,0.08)',
