import { useEffect, useRef } from 'react'
import { useLanguage } from '../contexts/LanguageContext'

export default function Hero() {
  const { t, lang } = useLanguage()
  const titleRef = useRef<HTMLHeadingElement>(null)

  useEffect(() => {
    const el = titleRef.current
    if (!el) return
    el.style.opacity = '0'
    el.style.transform = 'translateY(30px)'
    setTimeout(() => {
      el.style.transition = 'all 1s cubic-bezier(0.16,1,0.3,1)'
      el.style.opacity = '1'
      el.style.transform = 'translateY(0)'
    }, 100)
  }, [lang])

  return (
    <section id="hero" style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      position: 'relative',
      padding: '100px 24px 60px',
      overflow: 'hidden',
    }}>
      {/* Background glow orbs */}
      <div style={{
        position: 'absolute', top: '20%', right: '10%',
        width: 500, height: 500,
        background: 'radial-gradient(circle, rgba(14,165,233,0.12) 0%, transparent 70%)',
        borderRadius: '50%', pointerEvents: 'none',
      }} className="animate-float" />
      <div style={{
        position: 'absolute', bottom: '20%', left: '10%',
        width: 400, height: 400,
        background: 'radial-gradient(circle, rgba(139,92,246,0.1) 0%, transparent 70%)',
        borderRadius: '50%', pointerEvents: 'none',
        animationDelay: '-3s',
      }} className="animate-float" />

      {/* Rotating rings */}
      <div style={{
        position: 'absolute', top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        width: 700, height: 700,
        border: '1px solid rgba(14,165,233,0.06)',
        borderRadius: '50%', pointerEvents: 'none',
      }} className="animate-rotate-slow" />
      <div style={{
        position: 'absolute', top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        width: 500, height: 500,
        border: '1px solid rgba(139,92,246,0.08)',
        borderRadius: '50%', pointerEvents: 'none',
        animationDirection: 'reverse',
      }} className="animate-rotate-slow" />

      <div style={{
        position: 'relative', zIndex: 2,
        maxWidth: 900, margin: '0 auto',
        textAlign: 'center',
      }}>
        {/* Badge */}
        <div style={{
          display: 'inline-flex', alignItems: 'center', gap: '8px',
          padding: '6px 16px', borderRadius: '100px',
          background: 'rgba(14,165,233,0.1)',
          border: '1px solid rgba(14,165,233,0.25)',
          marginBottom: '32px',
          fontSize: '13px', color: '#0ea5e9', fontWeight: 600,
        }}>
          <span style={{
            width: 8, height: 8, borderRadius: '50%',
            background: '#0ea5e9', display: 'inline-block',
          }} className="animate-pulse-glow" />
          {t.hero.badge}
        </div>

        {/* Main Title */}
        <h1 ref={titleRef} style={{
          fontSize: 'clamp(36px, 7vw, 82px)',
          fontWeight: 900,
          lineHeight: 1.15,
          marginBottom: '24px',
          color: '#f1f5f9',
          letterSpacing: lang === 'en' ? '-2px' : '-1px',
        }}>
          {t.hero.title1}{' '}
          <span className="gradient-text">{t.hero.title2}</span>
        </h1>

        {/* Subtitle */}
        <p style={{
          fontSize: 'clamp(16px, 2.5vw, 20px)',
          color: '#64748b',
          maxWidth: 640, margin: '0 auto 40px',
          lineHeight: 1.7,
        }}>
          {t.hero.subtitle}
        </p>

        {/* CTA Buttons */}
        <div style={{
          display: 'flex', gap: '16px',
          justifyContent: 'center', flexWrap: 'wrap',
          marginBottom: '64px',
        }}>
          <a href="#pricing" className="neon-btn" style={{
            padding: '14px 36px', borderRadius: '12px',
            fontSize: '16px', fontWeight: 700,
            color: 'white', textDecoration: 'none',
            display: 'inline-block',
          }}>
            {t.hero.cta1}
          </a>
          <a href="#services" className="neon-outline" style={{
            padding: '14px 36px', borderRadius: '12px',
            fontSize: '16px', fontWeight: 600,
            textDecoration: 'none', display: 'inline-block',
          }}>
            {t.hero.cta2}
          </a>
        </div>

        {/* Dashboard Preview */}
        <div style={{ position: 'relative', maxWidth: 800, margin: '0 auto' }}>
          <div className="animate-pulse-glow" style={{
            borderRadius: '20px', overflow: 'hidden',
            border: '1px solid rgba(14,165,233,0.2)',
            background: 'rgba(8,15,30,0.8)',
            padding: '24px',
          }}>
            <DashboardMockup />
          </div>
          <div style={{
            position: 'absolute', bottom: -40, left: '50%',
            transform: 'translateX(-50%)',
            width: '80%', height: 60,
            background: 'radial-gradient(ellipse, rgba(14,165,233,0.3) 0%, transparent 70%)',
            filter: 'blur(20px)', pointerEvents: 'none',
          }} />
        </div>
      </div>
    </section>
  )
}

function DashboardMockup() {
  const { t, lang } = useLanguage()
  const kpis = [
    { label: t.hero.revenue, val: t.hero.revenueVal, color: '#22c55e' },
    { label: t.hero.clients, val: lang === 'ar' ? '١٢,٤٥٠' : '12,450', color: '#0ea5e9' },
    { label: t.hero.projects, val: lang === 'ar' ? '٣٤٨' : '348', color: '#8b5cf6' },
    { label: t.hero.satisfaction, val: lang === 'ar' ? '٩٨.٢٪' : '98.2%', color: '#f59e0b' },
  ]

  return (
    <div>
      {/* Top bar */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '20px' }}>
        <div style={{ width: 10, height: 10, borderRadius: '50%', background: '#ef4444' }} />
        <div style={{ width: 10, height: 10, borderRadius: '50%', background: '#f59e0b' }} />
        <div style={{ width: 10, height: 10, borderRadius: '50%', background: '#22c55e' }} />
        <div style={{ flex: 1, height: 28, background: 'rgba(14,165,233,0.08)', borderRadius: '6px', margin: '0 16px' }} />
        <span style={{ color: '#0ea5e9', fontSize: '12px' }}>{t.hero.dashTitle}</span>
      </div>

      {/* KPI Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: '12px', marginBottom: '20px' }}>
        {kpis.map((k) => (
          <div key={k.label} style={{
            background: 'rgba(14,165,233,0.05)',
            border: '1px solid rgba(14,165,233,0.1)',
            borderRadius: '10px', padding: '12px',
          }}>
            <div style={{ fontSize: '10px', color: '#64748b', marginBottom: '4px' }}>{k.label}</div>
            <div style={{ fontSize: '18px', fontWeight: 800, color: k.color }}>{k.val}</div>
          </div>
        ))}
      </div>

      {/* Charts */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '12px' }}>
        <div style={{
          background: 'rgba(8,15,30,0.6)',
          border: '1px solid rgba(14,165,233,0.1)',
          borderRadius: '10px', padding: '16px',
          height: 120, position: 'relative', overflow: 'hidden',
        }}>
          <div style={{ fontSize: '11px', color: '#64748b', marginBottom: '8px' }}>{t.hero.performance}</div>
          <svg width="100%" height="80" viewBox="0 0 300 80" preserveAspectRatio="none">
            <defs>
              <linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#0ea5e9" stopOpacity="0.4" />
                <stop offset="100%" stopColor="#0ea5e9" stopOpacity="0" />
              </linearGradient>
            </defs>
            <path d="M0,60 C40,50 60,20 100,30 C140,40 160,10 200,15 C240,20 270,8 300,5 L300,80 L0,80 Z"
              fill="url(#chartGrad)" />
            <path d="M0,60 C40,50 60,20 100,30 C140,40 160,10 200,15 C240,20 270,8 300,5"
              fill="none" stroke="#0ea5e9" strokeWidth="2" />
          </svg>
        </div>
        <div style={{
          background: 'rgba(8,15,30,0.6)',
          border: '1px solid rgba(139,92,246,0.1)',
          borderRadius: '10px', padding: '16px',
        }}>
          <div style={{ fontSize: '11px', color: '#64748b', marginBottom: '12px' }}>
            {lang === 'ar' ? 'توزيع الخدمات' : 'Services Split'}
          </div>
          {[
            { name: 'BI', pct: 42, color: '#0ea5e9' },
            { name: lang === 'ar' ? 'تصميم' : 'Design', pct: 31, color: '#8b5cf6' },
            { name: 'No-Code', pct: 27, color: '#06b6d4' },
          ].map((s) => (
            <div key={s.name} style={{ marginBottom: '8px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '10px', color: '#94a3b8', marginBottom: '3px' }}>
                <span>{s.name}</span><span>{s.pct}%</span>
              </div>
              <div style={{ height: 4, background: 'rgba(255,255,255,0.05)', borderRadius: '2px' }}>
                <div style={{ height: '100%', width: `${s.pct}%`, background: s.color, borderRadius: '2px' }} />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

