import { useState } from 'react'
import { useLanguage } from '../contexts/LanguageContext'

const planColors = ['#06b6d4', '#8b5cf6', '#f59e0b']
const planPopular = [false, true, false]
const planPrices = [
  { monthly: 1499, yearly: 999 },
  { monthly: 3999, yearly: 2799 },
  { monthly: 0, yearly: 0 },
]

export default function Pricing() {
  const { t, lang } = useLanguage()
  const [isYearly, setIsYearly] = useState(false)

  return (
    <section id="pricing" style={{ padding: '100px 24px', position: 'relative', zIndex: 1 }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <div style={{ textAlign: 'center', marginBottom: '48px' }} className="section-reveal">
          <div style={{
            display: 'inline-block', padding: '4px 16px', borderRadius: '100px',
            background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.2)',
            fontSize: '13px', color: '#f59e0b', marginBottom: '16px', fontWeight: 600,
          }}>
            {t.pricing.badge}
          </div>
          <h2 style={{ fontSize: 'clamp(28px, 5vw, 48px)', color: '#f1f5f9', marginBottom: '16px' }}>
            {t.pricing.title} <span className="gradient-text">{t.pricing.titleGrad}</span>
          </h2>
          <p style={{ color: '#64748b', fontSize: '17px', marginBottom: '32px' }}>
            {t.pricing.subtitle}
          </p>

          {/* Toggle */}
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: '12px',
            background: 'rgba(8,15,30,0.6)', border: '1px solid rgba(14,165,233,0.15)',
            borderRadius: '100px', padding: '4px',
          }}>
            {[false, true].map((yearly) => (
              <button key={String(yearly)} onClick={() => setIsYearly(yearly)} style={{
                padding: '8px 20px', borderRadius: '100px', border: 'none',
                cursor: 'pointer', fontSize: '14px', fontWeight: 600,
                fontFamily: 'Tajawal, sans-serif',
                background: isYearly === yearly ? 'linear-gradient(135deg, #0ea5e9, #8b5cf6)' : 'transparent',
                color: isYearly === yearly ? 'white' : '#64748b',
                transition: 'all 0.3s ease',
                display: 'flex', alignItems: 'center', gap: '6px',
              }}>
                {yearly ? t.pricing.yearly : t.pricing.monthly}
                {yearly && (
                  <span style={{
                    fontSize: '10px', padding: '2px 7px',
                    background: '#22c55e', borderRadius: '100px',
                    color: 'white', fontWeight: 700,
                  }}>{t.pricing.discount}</span>
                )}
              </button>
            ))}
          </div>
        </div>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '24px', alignItems: 'start',
        }}>
          {t.pricing.plans.map((plan, i) => {
            const color = planColors[i]
            const popular = planPopular[i]
            const price = planPrices[i]
            return (
              <div key={i} className="section-reveal" style={{
                borderRadius: '24px', padding: '32px',
                background: popular
                  ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(99,102,241,0.08))'
                  : 'rgba(8,15,30,0.7)',
                border: popular ? '2px solid rgba(139,92,246,0.5)' : '1px solid rgba(14,165,233,0.12)',
                position: 'relative', backdropFilter: 'blur(16px)',
                transform: popular ? 'scale(1.04)' : 'scale(1)',
                boxShadow: popular ? '0 30px 80px rgba(139,92,246,0.2)' : 'none',
                animationDelay: `${i * 150}ms`,
              }}>
                {popular && (
                  <div style={{
                    position: 'absolute', top: -14, left: '50%',
                    transform: 'translateX(-50%)',
                    background: 'linear-gradient(135deg, #8b5cf6, #0ea5e9)',
                    padding: '4px 20px', borderRadius: '100px',
                    fontSize: '12px', fontWeight: 700, color: 'white', whiteSpace: 'nowrap',
                  }}>
                    ⭐ {t.pricing.popular}
                  </div>
                )}
                <div style={{ fontSize: '12px', color, fontWeight: 700, marginBottom: '8px', letterSpacing: '1px' }}>
                  {plan.name}
                </div>
                <h3 style={{ fontSize: '24px', color: '#f1f5f9', marginBottom: '8px' }}>{plan.name}</h3>
                <p style={{ fontSize: '13px', color: '#64748b', marginBottom: '24px' }}>{plan.desc}</p>
                <div style={{ marginBottom: '28px' }}>
                  {price.monthly === 0 ? (
                    <div style={{ fontSize: '28px', fontWeight: 900, color }}>{t.pricing.custom}</div>
                  ) : (
                    <div>
                      <span style={{ fontSize: '44px', fontWeight: 900, color: '#f1f5f9' }}>
                        {lang === 'ar'
                          ? (isYearly ? price.yearly : price.monthly).toLocaleString('ar-SA')
                          : (isYearly ? Math.round(price.yearly / 3.75) : Math.round(price.monthly / 3.75)).toLocaleString()}
                      </span>
                      <span style={{ fontSize: '16px', color: '#64748b', marginInlineStart: '4px' }}>
                        {lang === 'ar' ? ' ر.س' : ' $'}{t.pricing.perMonth}
                      </span>
                    </div>
                  )}
                </div>
                <a href="#contact" style={{
                  display: 'block', textAlign: 'center', padding: '12px',
                  borderRadius: '12px', textDecoration: 'none',
                  fontWeight: 700, fontSize: '15px', marginBottom: '28px',
                  background: popular ? 'linear-gradient(135deg, #8b5cf6, #0ea5e9)' : `${color}20`,
                  color: popular ? 'white' : color,
                  border: popular ? 'none' : `1px solid ${color}40`,
                  transition: 'all 0.3s ease',
                }}>
                  {price.monthly === 0 ? t.pricing.contactUs : t.pricing.getStarted}
                </a>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                  {plan.features.map((f) => (
                    <div key={f} style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                      <span style={{ color: '#22c55e', fontSize: '14px', flexShrink: 0 }}>✓</span>
                      <span style={{ fontSize: '13px', color: '#94a3b8' }}>{f}</span>
                    </div>
                  ))}
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

