                  color: '#64748b', textDecoration: 'none', fontSize: '14px',
                  transition: 'all 0.3s ease',
                }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLElement).style.color = '#0ea5e9'
                  ;(e.currentTarget as HTMLElement).style.borderColor = 'rgba(14,165,233,0.4)'
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLElement).style.color = '#64748b'
                  ;(e.currentTarget as HTMLElement).style.borderColor = 'rgba(14,165,233,0.15)'
                }}>
                  {s.icon}
                </a>
              ))}
            </div>
          </div>

          {/* Links */}
          {Object.entries(t.footer.sections).map(([title, links]) => (
            <div key={title}>
              <h4 style={{ color: '#f1f5f9', fontSize: '15px', fontWeight: 700, marginBottom: '20px' }}>
                {title}
              </h4>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                {links.map((l) => (
                  <a key={l} href="#" style={{
                    color: '#64748b', textDecoration: 'none', fontSize: '14px',
                    transition: 'color 0.2s',
                  }}
                  onMouseEnter={(e) => (e.target as HTMLElement).style.color = '#0ea5e9'}
                  onMouseLeave={(e) => (e.target as HTMLElement).style.color = '#64748b'}>
                    {l}
                  </a>
                ))}
              </div>
            </div>
          ))}

          {/* Newsletter */}
          <div>
            <h4 style={{ color: '#f1f5f9', fontSize: '15px', fontWeight: 700, marginBottom: '16px' }}>
              {t.footer.newsletter}
            </h4>
            <p style={{ color: '#64748b', fontSize: '13px', marginBottom: '16px', lineHeight: 1.6 }}>
              {t.footer.newsletterDesc}
            </p>
            <div style={{ display: 'flex', gap: '8px', flexDirection: 'column' }}>
              <input
                type="email"
                placeholder={t.footer.emailPlaceholder}
                style={{
                  padding: '10px 14px', borderRadius: '10px',
                  background: 'rgba(14,165,233,0.05)',
                  border: '1px solid rgba(14,165,233,0.2)',
                  color: '#e2e8f0', fontSize: '14px',
                  outline: 'none', width: '100%',
                }}
              />
              <button className="neon-btn" style={{
                padding: '10px', borderRadius: '10px',
                color: 'white', fontSize: '14px', fontWeight: 600,
                cursor: 'pointer', width: '100%',
                fontFamily: 'Tajawal, sans-serif',
              }}>
                {t.footer.subscribe}
              </button>
            </div>
          </div>
        </div>

        {/* Bottom bar */}
        <div style={{
          borderTop: '1px solid rgba(14,165,233,0.08)', paddingTop: '32px',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          flexWrap: 'wrap', gap: '12px',
        }}>
          <div style={{ color: '#374151', fontSize: '13px' }}>{t.footer.copy}</div>
          <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <span style={{ fontSize: '12px', color: '#374151' }}>{t.footer.madeWith}</span>
            <span style={{ color: '#0ea5e9', fontSize: '16px' }}>❤</span>
            <span style={{ fontSize: '12px', color: '#374151' }}>{t.footer.inKSA}</span>
          </div>
        </div>
      </div>
    </footer>
  )
}

