              <div style={{ display: 'grid', gap: '20px', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))' }}>
                {result.charts.length === 0 ? (
                  <div style={{ color: '#64748b', textAlign: 'center', padding: '40px' }}>
                    {language === 'ar' ? 'لم يتم توليد charts' : 'No charts generated'}
                  </div>
                ) : result.charts.map((chart, i) => (
                  <div key={i} style={{
                    background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
                    borderRadius: '16px', overflow: 'hidden',
                  }}>
                    <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(79,158,255,0.1)', color: '#f1f5f9', fontWeight: 700 }}>
                      {chart.title}
                    </div>
                    <img src={`data:image/png;base64,${chart.data}`} alt={chart.title}
                      style={{ width: '100%', display: 'block' }} />
                    <div style={{ padding: '12px 20px' }}>
                      <a href={`data:image/png;base64,${chart.data}`} download={`${chart.title}.png`}
                        style={{ color: '#4f9eff', fontSize: '13px', fontWeight: 600, textDecoration: 'none' }}>
                        ⬇️ {language === 'ar' ? 'تحميل' : 'Download'}
                      </a>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Tab: Steps */}
            {activeTab === 'steps' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {result.steps.map((step, i) => (
                  <div key={i} style={{
                    background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.1)',
                    borderRadius: '12px', padding: '14px 18px',
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '6px' }}>
                      <span style={{
                        padding: '2px 10px', borderRadius: '20px', fontSize: '11px', fontWeight: 700,
                        background: step.type === 'tool_start' ? 'rgba(30,111,255,0.15)' :
                          step.type === 'tool_end' ? 'rgba(34,197,94,0.15)' : 'rgba(139,92,246,0.15)',
                        color: step.type === 'tool_start' ? '#4f9eff' :
                          step.type === 'tool_end' ? '#22c55e' : '#a78bfa',
                      }}>
                        {step.type}
                      </span>
                    </div>
                    <div style={{ fontSize: '12px', color: '#64748b', fontFamily: 'Courier New, monospace', whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                      {step.content.slice(0, 300)}{step.content.length > 300 ? '...' : ''}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes spin { to { transform: rotate(360deg); } }
        select option { background: #050d1e; }
      `}</style>
    </div>
  )
}

