            os.environ[k.strip()] = v.strip()

app = FastAPI(title="INTRSPOT BI Agent", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

API_KEY = os.getenv("ANTHROPIC_API_KEY", "")


def extract_excel_context(content: bytes, filename: str) -> tuple[pd.DataFrame, str]:
    """
    Smart Excel/CSV loader.
    Returns (df, raw_context_text).
    - df: best flat DataFrame found in the file
    - raw_context_text: full text representation of all tables in the file
    """
    raw_context = ""

    if filename.endswith(".csv"):
        df = pd.read_csv(io.BytesIO(content))
        raw_context = df.to_string(max_rows=200)
        return df, raw_context

    # For Excel: read raw (no headers) to extract all content
    try:
        xl = pd.ExcelFile(io.BytesIO(content))
        all_sections = []

        best_df = None
        best_row_count = 0

        for sheet_name in xl.sheet_names:
            raw = pd.read_excel(io.BytesIO(content), sheet_name=sheet_name, header=None)
            all_sections.append(f"\n=== Sheet: {sheet_name} ===")

            # Scan rows to find table sections and build context
            current_table_start = None
            current_headers = None
            tables_found = []

            for i, row in raw.iterrows():
                non_null = [str(v) for v in row if pd.notna(v) and str(v).strip() not in ['', 'nan']]
                if not non_null:
                    continue

                # Check if this looks like a header row (mostly strings, no numbers)
                is_header_candidate = sum(1 for v in non_null if not _is_numeric(v)) >= len(non_null) * 0.7
                all_sections.append(f"  Row {i}: {' | '.join(non_null)}")

                if is_header_candidate and len(non_null) >= 2:
                    # Try reading from this row as header
                    try:
                        candidate = pd.read_excel(
                            io.BytesIO(content), sheet_name=sheet_name,
                            header=i, nrows=50
                        )
                        # Clean: drop fully empty cols/rows
                        candidate = candidate.dropna(how='all').dropna(axis=1, how='all')
                        candidate.columns = [str(c).strip() for c in candidate.columns]
                        # Score: prefer tables with numeric data and proper headers
                        numeric_cols = candidate.select_dtypes(include=np.number).shape[1]
                        score = len(candidate) * numeric_cols
                        if score > best_row_count and len(candidate) >= 3:
                            best_row_count = score
                            best_df = candidate
                            tables_found.append({
                                "header_row": i,
                                "shape": candidate.shape,
                                "columns": candidate.columns.tolist()[:8]
                            })
                    except Exception:
                        pass

            if tables_found:
                all_sections.append(f"  [Tables detected: {len(tables_found)}]")
                for t in tables_found[:3]:
                    all_sections.append(f"  - Header at row {t['header_row']}, shape {t['shape']}, cols: {t['columns']}")

        raw_context = "\n".join(all_sections)

        # If no good flat table found, build a summary DataFrame from key rows
        if best_df is None or best_df.empty:
            raw2 = pd.read_excel(io.BytesIO(content), header=None)
            rows_data = []
            for i, row in raw2.iterrows():
                non_null = [str(v) for v in row if pd.notna(v) and str(v).strip() not in ['', 'nan']]
                if non_null:
                    rows_data.append({"row": i, "content": " | ".join(non_null)})
            best_df = pd.DataFrame(rows_data) if rows_data else pd.DataFrame()

        return best_df, raw_context

    except Exception as e:
        # Fallback: try standard read
        try:
            df = pd.read_excel(io.BytesIO(content))
            return df, df.to_string(max_rows=100)
        except Exception:
            raise ValueError(f"Cannot read file: {e}")


def _is_numeric(s: str) -> bool:
    try:
        float(s.replace(',', '').replace('%', ''))
        return True
    except ValueError:
        return False


def load_dataframe(file: UploadFile) -> tuple[pd.DataFrame, str]:
    content = file.file.read()
    filename = file.filename or ""
    return extract_excel_context(content, filename)


# ── Routes ─────────────────────────────────────────────────────────────────────

@app.get("/")
def root():
    return {"status": "INTRSPOT BI Agent is running"}


@app.get("/health")
def health():
    return {"status": "ok", "api_key_set": bool(API_KEY)}


@app.post("/analyze")
async def analyze(
    file: UploadFile = File(...),
    question: str = Form(default="حلّل هذه البيانات وأعطني أهم الرؤى مع لوحة تحكم كاملة"),
