import { useState, useRef } from 'react'

const API_URL = 'http://localhost:8001'

type Step = { type: string; content: string }
type Chart = { title: string; data: string }

type Result = {
  answer: string
  charts: Chart[]
  steps: Step[]
  dataset_info: { rows: number; columns: number; column_names: string[] }
}

export default function App() {
  const [file, setFile] = useState<File | null>(null)
  const [question, setQuestion] = useState('حلّل هذه البيانات وأعطني أهم الرؤى مع charts ولوحة تحكم كاملة')
  const [language, setLanguage] = useState<'ar' | 'en'>('ar')
  const [outputFormat, setOutputFormat] = useState('both')
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<Result | null>(null)
  const [error, setError] = useState('')
  const [activeTab, setActiveTab] = useState<'answer' | 'charts' | 'steps'>('answer')
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  const dir = language === 'ar' ? 'rtl' : 'ltr'

  const handleSubmit = async () => {
    if (!file) { setError(language === 'ar' ? 'يرجى رفع ملف' : 'Please upload a file'); return }
    setLoading(true); setError(''); setResult(null)
    try {
      const fd = new FormData()
      fd.append('file', file)
      fd.append('question', question)
      fd.append('language', language)
      fd.append('output_format', outputFormat)
      const res = await fetch(`${API_URL}/analyze`, { method: 'POST', body: fd })
      if (!res.ok) {
        const err = await res.json()
        throw new Error(err.detail || 'Server error')
      }
      const data = await res.json()
      setResult(data)
      setActiveTab('answer')
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Unknown error')
    } finally {
      setLoading(false)
    }
  }

  const copyCode = (text: string, i: number) => {
    navigator.clipboard.writeText(text)
    setCopiedIndex(i)
    setTimeout(() => setCopiedIndex(null), 2000)
  }

  // Extract code blocks from answer
  const parseAnswer = (text: string) => {
    const parts: { type: 'text' | 'code'; content: string; lang?: string }[] = []
    const regex = /```(\w*)\n?([\s\S]*?)```/g
    let last = 0; let match
    while ((match = regex.exec(text)) !== null) {
      if (match.index > last) parts.push({ type: 'text', content: text.slice(last, match.index) })
      parts.push({ type: 'code', content: match[2], lang: match[1] })
      last = match.index + match[0].length
    }
    if (last < text.length) parts.push({ type: 'text', content: text.slice(last) })
    return parts
  }

  return (
    <div dir={dir} style={{
      background: '#040812', minHeight: '100vh',
      fontFamily: "'Tajawal', sans-serif",
      color: '#f1f5f9',
    }}>
      {/* Header */}
      <header style={{
        borderBottom: '1px solid rgba(79,158,255,0.15)',
        padding: '18px 32px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        background: 'rgba(4,8,18,0.95)', backdropFilter: 'blur(20px)',
        position: 'sticky', top: 0, zIndex: 100,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{
            width: 40, height: 40, borderRadius: '10px',
            background: 'linear-gradient(135deg, #1e6fff, #4f9eff)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '16px', fontWeight: 900,
          }}>BI</div>
          <div>
            <div style={{ fontWeight: 800, fontSize: '17px', color: '#f1f5f9' }}>INTRSPOT BI Agent</div>
            <div style={{ fontSize: '11px', color: '#4f9eff' }}>
              {language === 'ar' ? 'وكيل ذكاء الأعمال' : 'Business Intelligence Agent'}
            </div>
          </div>
        </div>
        <button onClick={() => {
          setLanguage(l => l === 'ar' ? 'en' : 'ar')
          setQuestion(language === 'ar'
            ? 'Analyze this data and give me key insights with charts and a full dashboard'
            : 'حلّل هذه البيانات وأعطني أهم الرؤى مع charts ولوحة تحكم كاملة')
        }} style={{
          background: 'rgba(79,158,255,0.1)', border: '1px solid rgba(79,158,255,0.25)',
          color: '#4f9eff', padding: '7px 18px', borderRadius: '20px',
          cursor: 'pointer', fontSize: '13px', fontWeight: 700, fontFamily: 'Tajawal, sans-serif',
        }}>
          {language === 'ar' ? 'EN' : 'عربي'}
        </button>
      </header>

      <div style={{ maxWidth: 900, margin: '0 auto', padding: '40px 24px' }}>

        {/* Upload Card */}
        <div style={{
          background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
          borderRadius: '24px', padding: '36px', marginBottom: '32px',
        }}>
          <h1 style={{ fontSize: '26px', fontWeight: 900, marginBottom: '8px', color: '#f1f5f9' }}>
            {language === 'ar' ? '🤖 وكيل ذكاء الأعمال' : '🤖 BI Agent'}
          </h1>
          <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '28px' }}>
            {language === 'ar'
              ? 'ارفع ملف Excel أو CSV وسيحلله الوكيل ويبني لك لوحة تحكم كاملة'
              : 'Upload an Excel or CSV file and the agent will analyze it and build you a full dashboard'}
          </p>

          {/* File Upload */}
          <div
            onClick={() => fileRef.current?.click()}
            style={{
              border: `2px dashed ${file ? 'rgba(79,158,255,0.5)' : 'rgba(79,158,255,0.2)'}`,
              borderRadius: '16px', padding: '36px',
              textAlign: 'center', cursor: 'pointer', marginBottom: '20px',
              background: file ? 'rgba(30,111,255,0.05)' : 'transparent',
              transition: 'all 0.3s',
            }}
