        raise HTTPException(status_code=404, detail="Dataset not found. Please re-upload the file.")

    df = wdc_store[dataset_id]
    chunk = df.iloc[offset:offset + limit]

    # Remap column names to safe IDs
    col_map = {col: _safe_col_id(col) for col in df.columns}
    records = []
    for row in chunk.to_dict(orient="records"):
        clean = {}
        for k, v in row.items():
            safe_key = col_map[k]
            # Handle NaN / None
            if v is None or (isinstance(v, float) and v != v):
                clean[safe_key] = None
            else:
                clean[safe_key] = v
        records.append(clean)

    return JSONResponse(records)


