<script>
  var myConnector = tableau.makeConnector();
  var uploadedDatasetId = null;
  var uploadedSchema = null;
  var selectedFile = null;

  // ── Schema callback ──────────────────────────────────────────────────────────
  myConnector.getSchema = function(schemaCallback) {
    var conn = JSON.parse(tableau.connectionData);
    var tableSchema = {
      id: "intrspot_data",
      alias: "INTRSPOT: " + (conn.filename || "Dataset"),
      columns: conn.schema
    };
    schemaCallback([tableSchema]);
  };

  // ── Data callback ────────────────────────────────────────────────────────────
  myConnector.getData = function(table, doneCallback) {
    var conn = JSON.parse(tableau.connectionData);
    var url = conn.api_base + "/wdc/data/" + conn.dataset_id;

    $.ajax({
      url: url,
      type: "GET",
      success: function(data) {
        table.appendRows(data);
        doneCallback();
      },
      error: function(xhr) {
        tableau.abortWithError("Failed to fetch data: " + xhr.statusText);
      }
    });
  };

  tableau.registerConnector(myConnector);

  // ── File picker ──────────────────────────────────────────────────────────────
  $("#file-input").on("change", function() {
    var file = this.files[0];
    if (!file) return;
    selectedFile = file;
    var kb = (file.size / 1024).toFixed(1);
    var mb = (file.size / 1024 / 1024).toFixed(1);
    var sizeStr = file.size > 1048576 ? mb + " MB" : kb + " KB";
    $("#drop-icon").text("✅");
    $("#drop-label").addClass("active").text(file.name);
    $("#file-info").text(sizeStr);
    $("#drop-zone").addClass("has-file");
    $("#connect-btn").prop("disabled", false);
    setStatus("", "");
    $("#schema-preview").removeClass("visible").html("");
  });

  // ── Drag & drop ──────────────────────────────────────────────────────────────
  var dz = document.getElementById("drop-zone");
  dz.addEventListener("dragover", function(e) { e.preventDefault(); });
  dz.addEventListener("drop", function(e) {
    e.preventDefault();
    var file = e.dataTransfer.files[0];
    if (file) {
      var dt = new DataTransfer();
      dt.items.add(file);
      document.getElementById("file-input").files = dt.files;
      $("#file-input").trigger("change");
    }
  });

  // ── Connect button ───────────────────────────────────────────────────────────
  $("#connect-btn").on("click", function() {
    if (!selectedFile) { setStatus("Please select a file first.", "error"); return; }

    $("#connect-btn").prop("disabled", true);
    $("#steps-row").show();
    setStep(1);
    setStatus("Uploading file to INTRSPOT server...", "info");
    setProgress(20);

    var formData = new FormData();
    formData.append("file", selectedFile);

    var apiBase = window.location.origin;  // same server

    $.ajax({
      url: apiBase + "/wdc/upload",
      method: "POST",
      data: formData,
      processData: false,
      contentType: false,
      success: function(res) {
        uploadedDatasetId = res.dataset_id;
        uploadedSchema = res.schema;

        setStep(2);
        setProgress(60);
        setStatus("Schema detected: " + res.columns + " columns, " + res.rows.toLocaleString() + " rows.", "success");

        // Show schema preview
        var html = res.schema.map(function(c) {
          return '<div class="col-row"><span class="col-name">' + c.alias + '</span><span class="col-type">' + c.dataType + '</span></div>';
        }).join("");
        $("#schema-preview").html(html).addClass("visible");

        // Store connection data for Tableau
        tableau.connectionData = JSON.stringify({
          dataset_id: res.dataset_id,
          filename: res.filename,
          schema: res.schema,
          api_base: apiBase
        });
        tableau.connectionName = "INTRSPOT: " + (res.filename || "Dataset");

        setStep(3);
        setProgress(100);
        setTimeout(function() {
          setStatus("Connecting Tableau...", "info");
          tableau.submit();
        }, 600);
      },
      error: function(xhr) {
        var msg = "Upload failed";
        try { msg = JSON.parse(xhr.responseText).detail; } catch(e) {}
        setStatus("Error: " + msg, "error");
        $("#connect-btn").prop("disabled", false);
        setProgress(0);
      }
    });
  });

  // ── Helpers ──────────────────────────────────────────────────────────────────
  function setStatus(msg, type) {
    var el = $("#status");
    el.attr("class", "status" + (type ? " " + type : ""));
    el.text(msg);
  }

  function setStep(n) {
    for (var i = 1; i <= 3; i++) {
      var el = $("#s" + i);
      if (i < n) el.attr("class", "step done");
      else if (i === n) el.attr("class", "step active");
      else el.attr("class", "step");
    }
  }

  function setProgress(pct) {
    if (pct > 0) $("#progress").addClass("visible");
    else $("#progress").removeClass("visible");
    $("#progress-bar").css("width", pct + "%");
  }
</script>
</body>
</html>"""

"""
INTRSPOT BI Agent API — FastAPI Backend
"""
import os
import io
import json
import uuid
import pandas as pd
import numpy as np
from pathlib import Path
from fastapi import FastAPI, UploadFile, File, Form, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse, HTMLResponse
from dotenv import load_dotenv
from agent import BIAgent
from tableau_publisher import publish_datasource, list_server_info

# In-memory store for WDC + Tableau datasets
wdc_store: dict[str, pd.DataFrame] = {}

# Load .env from same directory as this file
env_path = Path(__file__).parent / ".env"
load_dotenv(dotenv_path=env_path, override=True)
if not os.getenv("ANTHROPIC_API_KEY") and env_path.exists():
    for line in env_path.read_text().splitlines():
        if "=" in line and not line.startswith("#"):
            k, v = line.split("=", 1)
            os.environ[k.strip()] = v.strip()

app = FastAPI(title="INTRSPOT BI Agent", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

API_KEY = os.getenv("ANTHROPIC_API_KEY", "")


def extract_excel_context(content: bytes, filename: str) -> tuple[pd.DataFrame, str]:
    """
    Smart Excel/CSV loader.
    Returns (df, raw_context_text).
    - df: best flat DataFrame (the sheet with most numeric rows)
    - raw_context_text: summary of all sheets for agent context
    """
    if filename.endswith(".csv"):
        df = pd.read_csv(io.BytesIO(content))
        raw_context = f"CSV file with {df.shape[0]} rows, {df.shape[1]} columns.\nColumns: {df.columns.tolist()}\n\nSample:\n{df.head(10).to_string()}"
        return df, raw_context

    try:
        xl = pd.ExcelFile(io.BytesIO(content))
        sheet_summaries = []
        best_df = None
        best_score = 0

        for sheet_name in xl.sheet_names:
            try:
                candidate = pd.read_excel(io.BytesIO(content), sheet_name=sheet_name)
                candidate = candidate.dropna(how='all').dropna(axis=1, how='all')

                # Fix unnamed headers
                unnamed_ratio = sum(1 for c in candidate.columns if 'Unnamed' in str(c)) / max(len(candidate.columns), 1)
                if unnamed_ratio > 0.5:
                    raw = pd.read_excel(io.BytesIO(content), sheet_name=sheet_name, header=None, nrows=15)
                    for i in range(min(10, len(raw))):
                        row_vals = [str(v) for v in raw.iloc[i] if pd.notna(v) and str(v).strip() not in ['', 'nan']]
                        if len(row_vals) >= 3 and sum(1 for v in row_vals if not _is_numeric(v)) >= 2:
                            try:
                                c2 = pd.read_excel(io.BytesIO(content), sheet_name=sheet_name, header=i)
                                c2 = c2.dropna(how='all').dropna(axis=1, how='all')
                                unnamed2 = sum(1 for c in c2.columns if 'Unnamed' in str(c)) / max(len(c2.columns), 1)
                                if unnamed2 < unnamed_ratio:
                                    candidate = c2
                                    unnamed_ratio = unnamed2
                                    break
                            except Exception:
                                pass

                numeric_cols = candidate.select_dtypes(include=np.number).shape[1]
                score = len(candidate) * numeric_cols

                # Concise summary only (to keep context small)
                num_df = candidate.select_dtypes(include=np.number)
                stats_str = ""
                if not num_df.empty:
                    desc = num_df.describe().round(1)
                    stats_str = f"\nStats: mean={desc.loc['mean'].to_dict()}, max={desc.loc['max'].to_dict()}"

                top_vals = {}
                for col in candidate.select_dtypes(include='object').columns[:2]:
                    top_vals[col] = candidate[col].value_counts().head(3).to_dict()

                sheet_summaries.append(
                    f"\n--- Sheet: '{sheet_name}' ({len(candidate)} rows, {len(candidate.columns)} cols) ---"
                    f"\nColumns: {candidate.columns.tolist()}"
                    f"{stats_str}"
                    f"\nTop categories: {top_vals}"
                    f"\nSample:\n{candidate.head(3).to_string()}"
                )

                if score > best_score:
                    best_score = score
                    best_df = candidate

            except Exception as e:
                sheet_summaries.append(f"--- Sheet: '{sheet_name}' ERROR: {e} ---")

        raw_context = "\n".join(sheet_summaries)

        if best_df is None or best_df.empty:
            raise ValueError("No readable data found in any sheet")

        return best_df, raw_context

    except Exception as e:
        try:
            df = pd.read_excel(io.BytesIO(content))
            return df, df.to_string(max_rows=100)
        except Exception:
            raise ValueError(f"Cannot read file: {e}")


def _is_numeric(s: str) -> bool:
    try:
        float(s.replace(',', '').replace('%', ''))
        return True
    except ValueError:
        return False


def load_dataframe(file: UploadFile) -> tuple[pd.DataFrame, str]:
    content = file.file.read()
    filename = file.filename or ""
    return extract_excel_context(content, filename)


