    .col-row { display: flex; gap: 8px; padding: 4px 0; border-bottom: 1px solid rgba(79,158,255,0.05); }
    .col-name { color: #e2e8f0; flex: 1; }
    .col-type { color: #4f9eff; font-size: 11px; background: rgba(79,158,255,0.1); padding: 1px 7px; border-radius: 10px; }
    .steps {
      margin-top: 20px;
      display: flex;
      gap: 8px;
    }
    .step {
      flex: 1;
      text-align: center;
      padding: 8px;
      border-radius: 8px;
      font-size: 11px;
      background: rgba(79,158,255,0.05);
      border: 1px solid rgba(79,158,255,0.1);
      color: #475569;
    }
    .step.done { background: rgba(34,197,94,0.1); border-color: rgba(34,197,94,0.2); color: #22c55e; }
    .step.active { background: rgba(79,158,255,0.1); border-color: rgba(79,158,255,0.3); color: #4f9eff; }
    .progress { width: 100%; background: rgba(79,158,255,0.1); border-radius: 4px; height: 4px; margin-top: 12px; overflow: hidden; display: none; }
    .progress.visible { display: block; }
    .progress-bar { height: 100%; background: linear-gradient(90deg, #1e6fff, #4f9eff); border-radius: 4px; transition: width 0.3s; }
  </style>
</head>
<body>
<div class="card">
  <div class="logo">
    <div class="logo-icon">BI</div>
    <div>
      <div class="logo-text">INTRSPOT</div>
      <div class="logo-sub">Tableau Web Data Connector</div>
    </div>
  </div>

  <h2>Connect Your Data to Tableau</h2>
  <p class="desc">Upload an Excel or CSV file. Tableau Desktop will automatically pull the data and schema — ready to build dashboards instantly.</p>

  <div class="drop-zone" id="drop-zone">
    <input type="file" id="file-input" accept=".csv,.xlsx,.xls">
    <div class="drop-icon" id="drop-icon">📂</div>
    <div class="drop-label" id="drop-label">Drag & drop file here, or click to browse</div>
    <div class="file-info" id="file-info"></div>
  </div>

  <button class="btn" id="connect-btn" disabled>Connect to Tableau</button>

  <div class="progress" id="progress"><div class="progress-bar" id="progress-bar" style="width:0%"></div></div>
  <div class="status" id="status"></div>

  <div class="schema-preview" id="schema-preview"></div>

  <div class="steps" id="steps-row" style="display:none">
    <div class="step" id="s1">① Upload</div>
    <div class="step" id="s2">② Schema</div>
    <div class="step" id="s3">③ Connect</div>
  </div>
</div>

<script>
  var myConnector = tableau.makeConnector();
  var uploadedDatasetId = null;
  var uploadedSchema = null;
  var selectedFile = null;

  // ── Schema callback ──────────────────────────────────────────────────────────
  myConnector.getSchema = function(schemaCallback) {
    var conn = JSON.parse(tableau.connectionData);
    var tableSchema = {
      id: "intrspot_data",
      alias: "INTRSPOT: " + (conn.filename || "Dataset"),
      columns: conn.schema
    };
    schemaCallback([tableSchema]);
  };

  // ── Data callback ────────────────────────────────────────────────────────────
  myConnector.getData = function(table, doneCallback) {
    var conn = JSON.parse(tableau.connectionData);
    var url = conn.api_base + "/wdc/data/" + conn.dataset_id;

    $.ajax({
      url: url,
      type: "GET",
      success: function(data) {
        table.appendRows(data);
        doneCallback();
      },
      error: function(xhr) {
        tableau.abortWithError("Failed to fetch data: " + xhr.statusText);
      }
    });
  };

  tableau.registerConnector(myConnector);

  // ── File picker ──────────────────────────────────────────────────────────────
  $("#file-input").on("change", function() {
    var file = this.files[0];
    if (!file) return;
    selectedFile = file;
    var kb = (file.size / 1024).toFixed(1);
    var mb = (file.size / 1024 / 1024).toFixed(1);
    var sizeStr = file.size > 1048576 ? mb + " MB" : kb + " KB";
    $("#drop-icon").text("✅");
    $("#drop-label").addClass("active").text(file.name);
    $("#file-info").text(sizeStr);
    $("#drop-zone").addClass("has-file");
    $("#connect-btn").prop("disabled", false);
    setStatus("", "");
    $("#schema-preview").removeClass("visible").html("");
  });

  // ── Drag & drop ──────────────────────────────────────────────────────────────
  var dz = document.getElementById("drop-zone");
  dz.addEventListener("dragover", function(e) { e.preventDefault(); });
  dz.addEventListener("drop", function(e) {
    e.preventDefault();
    var file = e.dataTransfer.files[0];
    if (file) {
      var dt = new DataTransfer();
      dt.items.add(file);
      document.getElementById("file-input").files = dt.files;
      $("#file-input").trigger("change");
    }
  });

  // ── Connect button ───────────────────────────────────────────────────────────
  $("#connect-btn").on("click", function() {
    if (!selectedFile) { setStatus("Please select a file first.", "error"); return; }

    $("#connect-btn").prop("disabled", true);
    $("#steps-row").show();
    setStep(1);
    setStatus("Uploading file to INTRSPOT server...", "info");
    setProgress(20);

    var formData = new FormData();
    formData.append("file", selectedFile);

    var apiBase = window.location.origin;  // same server

    $.ajax({
      url: apiBase + "/wdc/upload",
      method: "POST",
      data: formData,
      processData: false,
      contentType: false,
      success: function(res) {
        uploadedDatasetId = res.dataset_id;
        uploadedSchema = res.schema;

        setStep(2);
        setProgress(60);
        setStatus("Schema detected: " + res.columns + " columns, " + res.rows.toLocaleString() + " rows.", "success");

        // Show schema preview
        var html = res.schema.map(function(c) {
          return '<div class="col-row"><span class="col-name">' + c.alias + '</span><span class="col-type">' + c.dataType + '</span></div>';
        }).join("");
        $("#schema-preview").html(html).addClass("visible");

        // Store connection data for Tableau
        tableau.connectionData = JSON.stringify({
          dataset_id: res.dataset_id,
          filename: res.filename,
          schema: res.schema,
          api_base: apiBase
        });
        tableau.connectionName = "INTRSPOT: " + (res.filename || "Dataset");

        setStep(3);
        setProgress(100);
        setTimeout(function() {
          setStatus("Connecting Tableau...", "info");
          tableau.submit();
        }, 600);
      },
      error: function(xhr) {
        var msg = "Upload failed";
        try { msg = JSON.parse(xhr.responseText).detail; } catch(e) {}
        setStatus("Error: " + msg, "error");
        $("#connect-btn").prop("disabled", false);
        setProgress(0);
      }
    });
  });

  // ── Helpers ──────────────────────────────────────────────────────────────────
  function setStatus(msg, type) {
    var el = $("#status");
    el.attr("class", "status" + (type ? " " + type : ""));
    el.text(msg);
  }

  function setStep(n) {
    for (var i = 1; i <= 3; i++) {
      var el = $("#s" + i);
      if (i < n) el.attr("class", "step done");
      else if (i === n) el.attr("class", "step active");
      else el.attr("class", "step");
    }
  }

  function setProgress(pct) {
    if (pct > 0) $("#progress").addClass("visible");
    else $("#progress").removeClass("visible");
    $("#progress-bar").css("width", pct + "%");
  }
</script>
</body>
</html>"""

