import { useState, useRef } from 'react'

const API_URL = 'http://localhost:8001'

type Step = { type: string; content: string }
type Chart = { title: string; data: string }

type Result = {
  answer: string
  charts: Chart[]
  steps: Step[]
  dataset_info: { rows: number; columns: number; column_names: string[] }
}

export default function App() {
  const [file, setFile] = useState<File | null>(null)
  const [question, setQuestion] = useState('حلّل هذه البيانات وأعطني أهم الرؤى مع charts ولوحة تحكم كاملة')
  const [language, setLanguage] = useState<'ar' | 'en'>('ar')
  const [outputFormat, setOutputFormat] = useState('both')
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<Result | null>(null)
  const [error, setError] = useState('')
  const [activeTab, setActiveTab] = useState<'answer' | 'charts' | 'steps'>('answer')
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  const dir = language === 'ar' ? 'rtl' : 'ltr'

  const handleSubmit = async () => {
    if (!file) { setError(language === 'ar' ? 'يرجى رفع ملف' : 'Please upload a file'); return }
    setLoading(true); setError(''); setResult(null)
    try {
      const fd = new FormData()
      fd.append('file', file)
      fd.append('question', question)
      fd.append('language', language)
      fd.append('output_format', outputFormat)
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 300000) // 5 min
      let res: Response
      try {
        res = await fetch(`${API_URL}/analyze`, { method: 'POST', body: fd, signal: controller.signal })
      } finally {
        clearTimeout(timeoutId)
      }
      if (!res.ok) {
        const err = await res.json()
        throw new Error(err.detail || 'Server error')
      }
      const data = await res.json()
      setResult(data)
      setActiveTab('answer')
    } catch (e: unknown) {
      if (e instanceof Error && e.name === 'AbortError') {
        setError(language === 'ar' ? 'انتهت مهلة الطلب (5 دقائق) — حاول مجدداً' : 'Request timed out (5 min) — please try again')
      } else {
        setError(e instanceof Error ? e.message : 'Unknown error')
      }
    } finally {
      setLoading(false)
    }
  }

  const copyCode = (text: string, i: number) => {
    navigator.clipboard.writeText(text)
    setCopiedIndex(i)
    setTimeout(() => setCopiedIndex(null), 2000)
  }

  // Extract code blocks from answer
  const parseAnswer = (text: string) => {
    const parts: { type: 'text' | 'code'; content: string; lang?: string }[] = []
    const regex = /```(\w*)\n?([\s\S]*?)```/g
    let last = 0; let match
    while ((match = regex.exec(text)) !== null) {
      if (match.index > last) parts.push({ type: 'text', content: text.slice(last, match.index) })
      parts.push({ type: 'code', content: match[2], lang: match[1] })
      last = match.index + match[0].length
    }
    if (last < text.length) parts.push({ type: 'text', content: text.slice(last) })
    return parts
  }

  return (
    <div dir={dir} style={{
      background: '#040812', minHeight: '100vh',
      fontFamily: "'Tajawal', sans-serif",
      color: '#f1f5f9',
    }}>
      {/* Header */}
      <header style={{
        borderBottom: '1px solid rgba(79,158,255,0.15)',
        padding: '18px 32px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        background: 'rgba(4,8,18,0.95)', backdropFilter: 'blur(20px)',
        position: 'sticky', top: 0, zIndex: 100,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{
            width: 40, height: 40, borderRadius: '10px',
            background: 'linear-gradient(135deg, #1e6fff, #4f9eff)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '16px', fontWeight: 900,
          }}>BI</div>
          <div>
            <div style={{ fontWeight: 800, fontSize: '17px', color: '#f1f5f9' }}>INTRSPOT BI Agent</div>
            <div style={{ fontSize: '11px', color: '#4f9eff' }}>
              {language === 'ar' ? 'وكيل ذكاء الأعمال' : 'Business Intelligence Agent'}
            </div>
          </div>
        </div>
        <button onClick={() => {
          setLanguage(l => l === 'ar' ? 'en' : 'ar')
          setQuestion(language === 'ar'
            ? 'Analyze this data and give me key insights with charts and a full dashboard'
            : 'حلّل هذه البيانات وأعطني أهم الرؤى مع charts ولوحة تحكم كاملة')
        }} style={{
          background: 'rgba(79,158,255,0.1)', border: '1px solid rgba(79,158,255,0.25)',
          color: '#4f9eff', padding: '7px 18px', borderRadius: '20px',
          cursor: 'pointer', fontSize: '13px', fontWeight: 700, fontFamily: 'Tajawal, sans-serif',
        }}>
          {language === 'ar' ? 'EN' : 'عربي'}
        </button>
      </header>

      <div style={{ maxWidth: 900, margin: '0 auto', padding: '40px 24px' }}>

        {/* Upload Card */}
        <div style={{
          background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
          borderRadius: '24px', padding: '36px', marginBottom: '32px',
        }}>
          <h1 style={{ fontSize: '26px', fontWeight: 900, marginBottom: '8px', color: '#f1f5f9' }}>
            {language === 'ar' ? '🤖 وكيل ذكاء الأعمال' : '🤖 BI Agent'}
          </h1>
          <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '28px' }}>
            {language === 'ar'
              ? 'ارفع ملف Excel أو CSV وسيحلله الوكيل ويبني لك لوحة تحكم كاملة'
              : 'Upload an Excel or CSV file and the agent will analyze it and build you a full dashboard'}
          </p>

          {/* File Upload */}
          <div
            onClick={() => fileRef.current?.click()}
            style={{
              border: `2px dashed ${file ? 'rgba(79,158,255,0.5)' : 'rgba(79,158,255,0.2)'}`,
              borderRadius: '16px', padding: '36px',
              textAlign: 'center', cursor: 'pointer', marginBottom: '20px',
              background: file ? 'rgba(30,111,255,0.05)' : 'transparent',
              transition: 'all 0.3s',
            }}
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => {
              e.preventDefault()
              const f = e.dataTransfer.files[0]
              if (f) setFile(f)
            }}
          >
            <input ref={fileRef} type="file" accept=".csv,.xlsx,.xls" hidden
              onChange={(e) => { if (e.target.files?.[0]) setFile(e.target.files[0]) }} />
            <div style={{ fontSize: '40px', marginBottom: '12px' }}>{file ? '✅' : '📂'}</div>
            <div style={{ color: file ? '#4f9eff' : '#64748b', fontSize: '15px', fontWeight: 600 }}>
              {file ? file.name : (language === 'ar' ? 'اسحب الملف هنا أو اضغط للاختيار' : 'Drag file here or click to choose')}
            </div>
            {file && (
              <div style={{ color: '#475569', fontSize: '12px', marginTop: '6px' }}>
                {(file.size / 1024).toFixed(1)} KB
              </div>
            )}
          </div>

          {/* Question */}
          <textarea
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            rows={3}
            placeholder={language === 'ar' ? 'ماذا تريد من الوكيل؟' : 'What do you want from the agent?'}
            style={{
              width: '100%', padding: '14px', borderRadius: '12px',
              background: 'rgba(79,158,255,0.05)', border: '1px solid rgba(79,158,255,0.2)',
              color: '#e2e8f0', fontSize: '14px', resize: 'vertical',
              outline: 'none', marginBottom: '16px', fontFamily: 'Tajawal, sans-serif',
              direction: language === 'ar' ? 'rtl' : 'ltr',
              boxSizing: 'border-box',
            }}
          />

          {/* Options */}
          <div style={{ display: 'flex', gap: '12px', marginBottom: '24px', flexWrap: 'wrap' }}>
            <div style={{ flex: 1, minWidth: '180px' }}>
              <label style={{ fontSize: '12px', color: '#64748b', display: 'block', marginBottom: '6px' }}>
                {language === 'ar' ? 'المخرجات' : 'Output Format'}
              </label>
              <select value={outputFormat} onChange={(e) => setOutputFormat(e.target.value)}
                style={{
                  width: '100%', padding: '10px 12px', borderRadius: '10px',
                  background: 'rgba(79,158,255,0.05)', border: '1px solid rgba(79,158,255,0.2)',
                  color: '#e2e8f0', fontSize: '13px', fontFamily: 'Tajawal, sans-serif',
                }}>
                <option value="both">{language === 'ar' ? 'Power BI + Tableau' : 'Power BI + Tableau'}</option>
                <option value="powerbi">Power BI فقط</option>
                <option value="tableau">Tableau فقط</option>
                <option value="charts">{language === 'ar' ? 'Charts فقط' : 'Charts Only'}</option>
              </select>
            </div>
          </div>

          {error && (
            <div style={{
              background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.3)',
              borderRadius: '10px', padding: '12px 16px', marginBottom: '16px',
              color: '#f87171', fontSize: '14px',
            }}>⚠️ {error}</div>
          )}

          <button onClick={handleSubmit} disabled={loading} style={{
            width: '100%', padding: '14px',
            background: loading ? 'rgba(30,111,255,0.4)' : 'linear-gradient(135deg, #1e6fff, #4f9eff)',
            border: 'none', borderRadius: '12px',
            color: 'white', fontSize: '16px', fontWeight: 700,
            cursor: loading ? 'not-allowed' : 'pointer',
            fontFamily: 'Tajawal, sans-serif',
            transition: 'all 0.3s',
            boxShadow: loading ? 'none' : '0 0 30px rgba(30,111,255,0.35)',
          }}>
            {loading
              ? (language === 'ar' ? '🔄 الوكيل يعمل...' : '🔄 Agent working...')
              : (language === 'ar' ? '🚀 تحليل البيانات' : '🚀 Analyze Data')}
          </button>
        </div>

        {/* Loading */}
        {loading && (
          <div style={{
            background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
            borderRadius: '16px', padding: '28px', textAlign: 'center', marginBottom: '24px',
          }}>
            <div style={{ fontSize: '32px', marginBottom: '12px', animation: 'spin 1s linear infinite', display: 'inline-block' }}>⚙️</div>
            <div style={{ color: '#4f9eff', fontWeight: 700, fontSize: '16px', marginBottom: '8px' }}>
              {language === 'ar' ? 'الوكيل يحلل البيانات...' : 'Agent is analyzing your data...'}
            </div>
            <div style={{ color: '#475569', fontSize: '13px' }}>
              {language === 'ar' ? 'قد يستغرق ذلك 30-60 ثانية' : 'This may take 30-60 seconds'}
            </div>
            <div style={{
              display: 'flex', gap: '8px', justifyContent: 'center', marginTop: '20px',
            }}>
              {['تحليل البيانات', 'رسم Charts', 'توليد الكود', 'كتابة التقرير'].map((s, i) => (
                <div key={i} style={{
                  padding: '5px 12px', borderRadius: '20px', fontSize: '11px',
                  background: 'rgba(79,158,255,0.1)', color: '#4f9eff',
                  border: '1px solid rgba(79,158,255,0.2)',
                }}>{s}</div>
              ))}
            </div>
          </div>
        )}

        {/* Results */}
        {result && (
          <div>
            {/* Dataset info bar */}
            <div style={{
              display: 'flex', gap: '16px', marginBottom: '20px', flexWrap: 'wrap',
            }}>
              {[
                { label: language === 'ar' ? 'الصفوف' : 'Rows', val: result.dataset_info.rows.toLocaleString() },
                { label: language === 'ar' ? 'الأعمدة' : 'Columns', val: result.dataset_info.columns },
                { label: language === 'ar' ? 'الرسوم البيانية' : 'Charts', val: result.charts.length },
                { label: language === 'ar' ? 'خطوات الوكيل' : 'Agent Steps', val: result.steps.length },
              ].map((item) => (
                <div key={item.label} style={{
                  flex: 1, minWidth: '100px',
                  background: 'rgba(30,111,255,0.08)', border: '1px solid rgba(79,158,255,0.2)',
                  borderRadius: '12px', padding: '14px 20px', textAlign: 'center',
                }}>
                  <div style={{ fontSize: '24px', fontWeight: 900, color: '#4f9eff' }}>{item.val}</div>
                  <div style={{ fontSize: '12px', color: '#64748b' }}>{item.label}</div>
                </div>
              ))}
            </div>

            {/* Tabs */}
            <div style={{ display: 'flex', gap: '4px', marginBottom: '20px', background: 'rgba(8,15,30,0.8)', borderRadius: '12px', padding: '4px', width: 'fit-content' }}>
              {[
                { key: 'answer', label: language === 'ar' ? '📝 التقرير' : '📝 Report' },
                { key: 'charts', label: `📊 Charts (${result.charts.length})` },
                { key: 'steps', label: language === 'ar' ? `⚙️ خطوات الوكيل (${result.steps.length})` : `⚙️ Steps (${result.steps.length})` },
              ].map((tab) => (
                <button key={tab.key} onClick={() => setActiveTab(tab.key as 'answer' | 'charts' | 'steps')}
                  style={{
                    padding: '8px 20px', borderRadius: '8px', border: 'none',
                    cursor: 'pointer', fontSize: '13px', fontWeight: 600,
                    fontFamily: 'Tajawal, sans-serif',
                    background: activeTab === tab.key ? 'linear-gradient(135deg,#1e6fff,#4f9eff)' : 'transparent',
                    color: activeTab === tab.key ? 'white' : '#64748b',
                    transition: 'all 0.2s',
                  }}>
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Tab: Answer */}
            {activeTab === 'answer' && (
              <div style={{
                background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
                borderRadius: '16px', padding: '28px',
              }}>
                {parseAnswer(result.answer).map((part, i) => (
                  part.type === 'text' ? (
                    <p key={i} style={{ color: '#cbd5e1', lineHeight: 1.8, fontSize: '15px', whiteSpace: 'pre-wrap', marginBottom: '12px' }}>
                      {part.content}
                    </p>
                  ) : (
                    <div key={i} style={{ position: 'relative', marginBottom: '16px' }}>
                      <div style={{
                        background: 'rgba(4,8,18,0.9)', border: '1px solid rgba(79,158,255,0.2)',
                        borderRadius: '10px', padding: '16px',
                        fontSize: '13px', color: '#94a3b8',
                        fontFamily: 'Courier New, monospace',
                        overflow: 'auto', maxHeight: '400px',
                      }}>
                        {part.lang && (
                          <div style={{ color: '#4f9eff', fontSize: '11px', marginBottom: '8px', fontFamily: 'Tajawal, sans-serif' }}>
                            {part.lang.toUpperCase()}
                          </div>
                        )}
                        <pre style={{ margin: 0, whiteSpace: 'pre-wrap' }}>{part.content}</pre>
                      </div>
                      <button onClick={() => copyCode(part.content, i)} style={{
                        position: 'absolute', top: '10px',
                        left: dir === 'rtl' ? '10px' : undefined,
                        right: dir === 'ltr' ? '10px' : undefined,
                        background: 'rgba(79,158,255,0.15)', border: '1px solid rgba(79,158,255,0.3)',
                        color: '#4f9eff', padding: '4px 10px', borderRadius: '6px',
                        cursor: 'pointer', fontSize: '11px', fontFamily: 'Tajawal, sans-serif',
                      }}>
                        {copiedIndex === i ? '✅' : '📋'}
                      </button>
                    </div>
                  )
                ))}
              </div>
            )}

            {/* Tab: Charts */}
            {activeTab === 'charts' && (
              <div style={{ display: 'grid', gap: '20px', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))' }}>
                {result.charts.length === 0 ? (
                  <div style={{ color: '#64748b', textAlign: 'center', padding: '40px' }}>
                    {language === 'ar' ? 'لم يتم توليد charts' : 'No charts generated'}
                  </div>
                ) : result.charts.map((chart, i) => (
                  <div key={i} style={{
                    background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.15)',
                    borderRadius: '16px', overflow: 'hidden',
                  }}>
                    <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(79,158,255,0.1)', color: '#f1f5f9', fontWeight: 700 }}>
                      {chart.title}
                    </div>
                    <img src={`data:image/png;base64,${chart.data}`} alt={chart.title}
                      style={{ width: '100%', display: 'block' }} />
                    <div style={{ padding: '12px 20px' }}>
                      <a href={`data:image/png;base64,${chart.data}`} download={`${chart.title}.png`}
                        style={{ color: '#4f9eff', fontSize: '13px', fontWeight: 600, textDecoration: 'none' }}>
                        ⬇️ {language === 'ar' ? 'تحميل' : 'Download'}
                      </a>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Tab: Steps */}
            {activeTab === 'steps' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {result.steps.map((step, i) => (
                  <div key={i} style={{
                    background: 'rgba(8,15,30,0.8)', border: '1px solid rgba(79,158,255,0.1)',
                    borderRadius: '12px', padding: '14px 18px',
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '6px' }}>
                      <span style={{
                        padding: '2px 10px', borderRadius: '20px', fontSize: '11px', fontWeight: 700,
                        background: step.type === 'tool_start' ? 'rgba(30,111,255,0.15)' :
                          step.type === 'tool_end' ? 'rgba(34,197,94,0.15)' : 'rgba(139,92,246,0.15)',
                        color: step.type === 'tool_start' ? '#4f9eff' :
                          step.type === 'tool_end' ? '#22c55e' : '#a78bfa',
                      }}>
                        {step.type}
                      </span>
                    </div>
                    <div style={{ fontSize: '12px', color: '#64748b', fontFamily: 'Courier New, monospace', whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                      {step.content.slice(0, 300)}{step.content.length > 300 ? '...' : ''}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes spin { to { transform: rotate(360deg); } }
        select option { background: #050d1e; }
      `}</style>
    </div>
  )
}

