# ── Routes ─────────────────────────────────────────────────────────────────────

@app.get("/")
def root():
    return {"status": "INTRSPOT BI Agent is running"}


@app.get("/health")
def health():
    return {"status": "ok", "api_key_set": bool(API_KEY)}


@app.post("/analyze")
async def analyze(
    file: UploadFile = File(...),
    question: str = Form(default="حلّل هذه البيانات وأعطني أهم الرؤى مع لوحة تحكم كاملة"),
    language: str = Form(default="ar"),
    output_format: str = Form(default="both"),
):
    if not API_KEY or API_KEY == "your_api_key_here":
        raise HTTPException(status_code=500, detail="ANTHROPIC_API_KEY not configured")

    try:
        df, raw_context = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read file: {str(e)}")

    if df.empty:
        raise HTTPException(status_code=400, detail="File is empty or unreadable")

    format_instruction = {
        "powerbi": "Generate Power BI DAX measures and M Query. ",
        "tableau": "Generate Tableau Calculated Fields. ",
        "both": "Generate both Power BI and Tableau code. ",
        "charts": "Focus on charts and visualizations. ",
    }.get(output_format, "")

    lang_instruction = "Respond in Arabic. " if language == "ar" else "Respond in English. "
    full_question = f"{lang_instruction}{format_instruction}{question}"

    agent = BIAgent(api_key=API_KEY)
    steps_log = []

    def on_step(step_type, content):
        steps_log.append({
            "type": step_type,
            "content": content if isinstance(content, str) else json.dumps(content, ensure_ascii=False)
        })

    result = agent.run(full_question, df, on_step=on_step, raw_context=raw_context)

    return JSONResponse({
        "success": True,
        "answer": result["answer"],
        "charts": result["charts"],
        "steps": steps_log,
        "dataset_info": {
            "rows": int(df.shape[0]),
            "columns": int(df.shape[1]),
            "column_names": df.columns.tolist(),
        }
    })


@app.post("/quick-stats")
async def quick_stats(file: UploadFile = File(...)):
    try:
        df, raw_context = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))

    numeric = df.select_dtypes(include=np.number)

    return {
        "rows": int(df.shape[0]),
        "columns": int(df.shape[1]),
        "column_names": df.columns.tolist(),
        "numeric_columns": numeric.columns.tolist(),
        "text_columns": df.select_dtypes(include="object").columns.tolist(),
        "nulls": {k: int(v) for k, v in df.isnull().sum().items()},
        "sample": df.head(5).fillna("").to_dict(orient="records"),
        "numeric_summary": numeric.describe().round(2).to_dict() if not numeric.empty else {},
        "raw_context_preview": raw_context[:1000] if raw_context else "",
    }


# ── Tableau Server / Online ────────────────────────────────────────────────────

@app.post("/tableau/publish")
async def tableau_publish(
    file: UploadFile = File(...),
    datasource_name: str = Form(...),
    server_url: str = Form(...),
    token_name: str = Form(...),
    token_value: str = Form(...),
    site_id: str = Form(default=""),
    project_name: str = Form(default="Default"),
):
    """
    Upload file → publish as .hyper datasource to Tableau Server/Online.
    """
    try:
        df, _ = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read file: {e}")

    if df.empty:
        raise HTTPException(status_code=400, detail="File is empty")

    try:
        result = publish_datasource(
            df=df,
            datasource_name=datasource_name,
            server_url=server_url,
            token_name=token_name,
            token_value=token_value,
            site_id=site_id,
            project_name=project_name,
        )
        return JSONResponse(result)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Publish failed: {str(e)}")


@app.post("/tableau/info")
async def tableau_info(
    server_url: str = Form(...),
    token_name: str = Form(...),
    token_value: str = Form(...),
    site_id: str = Form(default=""),
):
    """
    List projects, datasources, and workbooks from Tableau Server.
    """
    try:
        info = list_server_info(server_url, token_name, token_value, site_id)
        return JSONResponse(info)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Connection failed: {str(e)}")


# ── Tableau Web Data Connector ──────────────────────────────────────────────────

def _tableau_col_type(dtype) -> str:
    if pd.api.types.is_integer_dtype(dtype):
        return "int"
    elif pd.api.types.is_float_dtype(dtype):
        return "float"
    elif pd.api.types.is_datetime64_any_dtype(dtype):
        return "datetime"
    elif pd.api.types.is_bool_dtype(dtype):
        return "bool"
    else:
        return "string"


def _safe_col_id(name: str) -> str:
    """Convert column name to a safe Tableau field ID."""
    import re
    safe = re.sub(r'[^a-zA-Z0-9_]', '_', str(name))
    if safe[0].isdigit():
        safe = "col_" + safe
    return safe.lower()[:50]


@app.post("/wdc/upload")
async def wdc_upload(file: UploadFile = File(...)):
    """Upload file → store it → return dataset_id + schema for WDC."""
    try:
        df, _ = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))

    if df.empty:
        raise HTTPException(status_code=400, detail="File is empty")

    dataset_id = str(uuid.uuid4())[:12]
    # Convert datetime cols to string for JSON serialization
    df_clean = df.copy()
    for col in df_clean.select_dtypes(include=['datetime64']).columns:
        df_clean[col] = df_clean[col].astype(str)

    wdc_store[dataset_id] = df_clean

    schema = [
        {
            "id": _safe_col_id(col),
            "alias": str(col),
            "dataType": _tableau_col_type(df[col].dtype)
        }
        for col in df.columns
    ]

    return {
        "dataset_id": dataset_id,
        "filename": file.filename,
        "rows": int(df.shape[0]),
        "columns": int(df.shape[1]),
        "schema": schema,
    }


@app.get("/wdc/data/{dataset_id}")
async def wdc_data(dataset_id: str, offset: int = 0, limit: int = 50000):
    """Return dataset rows as JSON array for Tableau WDC getData()."""
    if dataset_id not in wdc_store:
        raise HTTPException(status_code=404, detail="Dataset not found. Please re-upload the file.")

    df = wdc_store[dataset_id]
    chunk = df.iloc[offset:offset + limit]

    # Remap column names to safe IDs
    col_map = {col: _safe_col_id(col) for col in df.columns}
    records = []
    for row in chunk.to_dict(orient="records"):
        clean = {}
        for k, v in row.items():
            safe_key = col_map[k]
            # Handle NaN / None
            if v is None or (isinstance(v, float) and v != v):
                clean[safe_key] = None
            else:
                clean[safe_key] = v
        records.append(clean)

    return JSONResponse(records)


@app.get("/wdc/info/{dataset_id}")
async def wdc_info(dataset_id: str):
    """Check if dataset is still in memory."""
    if dataset_id not in wdc_store:
        raise HTTPException(status_code=404, detail="Dataset expired")
    df = wdc_store[dataset_id]
    return {"rows": int(df.shape[0]), "columns": int(df.shape[1])}


@app.get("/wdc", response_class=HTMLResponse)
async def wdc_page():
    """Serve the Tableau Web Data Connector HTML page."""
    return HTMLResponse(content=WDC_HTML)


